col = Reflect.construct(Intl.Collator, [], newTarget);
assert.sameValue(Object.getPrototypeOf(col), other.Intl.Collator.prototype, 'newTarget.prototype is undefined');

newTarget.prototype = null;
col = Reflect.construct(Intl.Collator, [], newTarget);
